example.code:
#include <iostream>

int main()
{
    char x = 'a';
    char y = 'c';

    std::cout << ++x << std::endl; // 'a' + 1 = 'b'
    std::cout << y++ << std::endl; // prints 'c', then y becomes 'd'
    std::cout << (x - y) << std::endl; // 'b' (98) - 'd' (100) = -2

    int i = '1';
    int j = '1' + '2'; // 49 + 50
    int k = 'a';
    char c = 90; // ASCII for 'Z'
    std::cout << i << " " << j << " " << k << " " << c << std::endl;

    return 0;
}

